#!/usr/bin/env node
/**
 * Dark mode for page-specific styles.
 *
 * Many components style their own classes with light colours (`@apply bg-white text-slate-900`,
 * `background: white`). Those don't use the shared Tailwind classes that assets/dark.css maps, so
 * this script reads every component's <style> blocks and adds a dark block to the same component:
 *
 *   <style scoped>
 *   /* dark mode: generated by scripts/build-dark-overrides.cjs *\/
 *   html.dark .card-x { background-color: var(--d-surface); }
 *   </style>
 *
 * Keeping the rules inside the component keeps them scoped to it, so two components that both
 * have a ".pill" class don't change each other.
 *
 *   node scripts/build-dark-overrides.cjs
 *
 * Run it again after changing a component's styles; it replaces its own block. Login.vue styles
 * its dark look by hand and is skipped, as is any selector a component already gives a
 * hand-written html.dark rule.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const SRC = path.join(ROOT, 'src');
const MARK = '/* dark mode: generated by scripts/build-dark-overrides.cjs */';
const SKIP = new Set(['Login.vue']);

// ---- Colour helpers -------------------------------------------------------------------------
const NAMED = { white: [255, 255, 255], black: [0, 0, 0] };
const parseColor = (v) => {
  v = v.trim().toLowerCase();
  if (NAMED[v]) return NAMED[v];
  let m = v.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/);
  if (m) {
    const h = m[1].length === 3 ? m[1].split('').map((c) => c + c).join('') : m[1];
    return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16));
  }
  m = v.match(/^rgba?\(\s*(\d+)[ ,]+(\d+)[ ,]+(\d+)/);
  return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : null;
};
const lightness = ([r, g, b]) => (Math.max(r, g, b) + Math.min(r, g, b)) / 510;
const firstColor = (value) => {
  const m = value.match(/#[0-9a-fA-F]{3,6}\b|rgba?\([^)]*\)|\bwhite\b|\bblack\b/);
  return m ? parseColor(m[0]) : null;
};

// ---- Tailwind tokens -> dark values ---------------------------------------------------------
const TINT = {
  brand: '34, 197, 94', green: '34, 197, 94', emerald: '16, 185, 129', teal: '20, 184, 166',
  red: '239, 68, 68', rose: '244, 63, 94', amber: '245, 158, 11', yellow: '234, 179, 8', orange: '249, 115, 22',
  sky: '56, 189, 248', blue: '59, 130, 246', indigo: '99, 102, 241', violet: '139, 92, 246', purple: '168, 85, 247',
};
const LIGHT_TEXT = {
  brand: '#86efac', green: '#86efac', emerald: '#6ee7b7', teal: '#5eead4', red: '#fca5a5', rose: '#fda4af',
  amber: '#fcd34d', yellow: '#fde047', orange: '#fdba74', sky: '#7dd3fc', blue: '#93c5fd', indigo: '#a5b4fc',
  violet: '#c4b5fd', purple: '#d8b4fe',
};
const NEUTRAL = /^(gray|slate|zinc|neutral|stone)$/;

/** One Tailwind token (no variant) -> [property, value] in dark mode, or null to leave it alone. */
const tokenToDark = (token) => {
  let m = token.match(/^bg-white(\/\d+)?$/);
  if (m) return ['background-color', 'var(--d-surface)'];
  m = token.match(/^bg-([a-z]+)-(\d+)(\/\d+)?$/);
  if (m) {
    const [, c, s] = m;
    const shade = Number(s);
    if (NEUTRAL.test(c)) {
      if (shade <= 50) return ['background-color', 'var(--d-sunken)'];
      if (shade <= 100) return ['background-color', 'var(--d-raised)'];
      if (shade <= 200) return ['background-color', 'var(--d-line)'];
      if (shade <= 300) return ['background-color', 'var(--d-line-strong)'];
      return null;
    }
    if (TINT[c] && shade <= 100) return ['background-color', `rgba(${TINT[c]}, ${shade <= 50 ? 0.12 : 0.2})`];
    if (TINT[c] && shade <= 200) return ['background-color', `rgba(${TINT[c]}, 0.28)`];
    return null;
  }
  m = token.match(/^text-([a-z]+)-(\d+)$/);
  if (m) {
    const [, c, s] = m;
    const shade = Number(s);
    if (NEUTRAL.test(c)) {
      if (shade >= 800) return ['color', 'var(--d-text)'];
      if (shade >= 700) return ['color', 'var(--d-text-2)'];
      if (shade >= 600) return ['color', 'var(--d-text-3)'];
      if (shade >= 500) return ['color', 'var(--d-muted)'];
      if (shade >= 400) return ['color', 'var(--d-faint)'];
      return null;
    }
    if (LIGHT_TEXT[c] && shade >= 600) return ['color', LIGHT_TEXT[c]];
    return null;
  }
  if (token === 'text-black') return ['color', 'var(--d-text)'];
  m = token.match(/^border-([a-z]+)-(\d+)(\/\d+)?$/);
  if (m) {
    const [, c, s] = m;
    const shade = Number(s);
    if (NEUTRAL.test(c)) return shade <= 200 ? ['border-color', 'var(--d-line)'] : shade <= 400 ? ['border-color', 'var(--d-line-strong)'] : null;
    if (TINT[c] && shade <= 300) return ['border-color', `rgba(${TINT[c]}, 0.3)`];
    return null;
  }
  if (/^border-white(\/\d+)?$/.test(token)) return ['border-color', 'var(--d-line)'];
  m = token.match(/^ring-([a-z]+)-(\d+)(\/\d+)?$/);
  if (m) {
    const [, c, s] = m;
    if (NEUTRAL.test(c) && Number(s) <= 300) return ['--tw-ring-color', 'var(--d-line-strong)'];
    if (TINT[c] && Number(s) <= 300) return ['--tw-ring-color', `rgba(${TINT[c]}, 0.3)`];
    return null;
  }
  m = token.match(/^divide-([a-z]+)-(\d+)$/);
  if (m && NEUTRAL.test(m[1]) && Number(m[2]) <= 300) return ['divide', 'var(--d-line)'];
  return null;
};

/** A plain CSS declaration -> dark replacement, or null. */
const declToDark = (prop, value) => {
  prop = prop.trim().toLowerCase();
  if (/gradient|url\(|var\(/.test(value)) return null;
  const col = firstColor(value);
  if (!col) return null;
  const L = lightness(col);
  if ((prop === 'background' || prop === 'background-color') && L > 0.88) return ['background-color', L > 0.96 ? 'var(--d-surface)' : 'var(--d-sunken)'];
  if (/^border(-(top|right|bottom|left))?(-color)?$/.test(prop) && L > 0.75) return [prop.endsWith('-color') ? prop : `${prop}-color`, 'var(--d-line)'];
  if (prop === 'color' && L < 0.4) return ['color', L < 0.2 ? 'var(--d-text)' : 'var(--d-text-2)'];
  return null;
};

// ---- CSS parsing (flat rules + @media blocks, enough for these components) ------------------
const stripComments = (css) => css.replace(/\/\*[\s\S]*?\*\//g, '');
function* rules(css) {
  let i = 0;
  while (i < css.length) {
    const open = css.indexOf('{', i);
    if (open < 0) return;
    const head = css.slice(i, open).trim();
    let depth = 1;
    let j = open + 1;
    while (j < css.length && depth) {
      if (css[j] === '{') depth++;
      else if (css[j] === '}') depth--;
      j++;
    }
    const body = css.slice(open + 1, j - 1);
    if (head.startsWith('@media') || head.startsWith('@supports')) {
      for (const r of rules(body)) yield { ...r, at: head };
    } else if (!head.startsWith('@')) {
      yield { selector: head, body };
    }
    i = j;
  }
}

const scopedFiles = [];
const walk = (dir) => fs.readdirSync(dir, { withFileTypes: true }).forEach((e) => {
  const p = path.join(dir, e.name);
  if (e.isDirectory()) walk(p);
  else if (e.name.endsWith('.vue') && !SKIP.has(e.name)) scopedFiles.push(p);
});
walk(SRC);

let changed = 0;
let total = 0;
for (const file of scopedFiles.sort()) {
  const raw = fs.readFileSync(file, 'utf8');
  const crlf = raw.includes('\r\n');
  // Drop the block this script wrote last time, then read what is left.
  let text = raw.replace(/\r\n/g, '\n').replace(new RegExp(`\\n*<style\\b[^>]*>\\n${MARK.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&')}[\\s\\S]*?<\\/style>\\n?`), '\n');
  const blocks = [...text.matchAll(/<style\b([^>]*)>([\s\S]*?)<\/style>/g)];
  if (!blocks.length) continue;
  const scoped = /\bscoped\b/.test(blocks[0][1]);
  const css = blocks.map((m) => m[2]).join('\n');
  // Selectors the component already darkens by hand.
  const handled = new Set([...css.matchAll(/(?:^|[},])\s*html\.dark\s+([^{,]+?)\s*[{,]/g)].map((m) => m[1].trim()));

  const fileRules = [];
  for (const { selector, body, at } of rules(stripComments(css))) {
    if (/:global|:deep|::v-deep|html\.dark|^(html|body|:root)\b|@keyframes|^\d|^from$|^to$/.test(selector)) continue;
    const sels = selector.split(',').map((x) => x.trim()).filter((x) => x && !handled.has(x));
    if (!sels.length) continue;
    const base = [];
    const hover = [];
    for (const decl of body.split(';')) {
      const d = decl.trim();
      if (!d) continue;
      if (d.startsWith('@apply')) {
        for (const token of d.slice(6).trim().split(/\s+/)) {
          const at2 = token.lastIndexOf(':');
          const variant = at2 >= 0 ? token.slice(0, at2) : '';
          if (variant && variant !== 'hover') continue;
          const dark = tokenToDark(token.slice(at2 + 1).replace(/^!/, ''));
          if (dark) (variant === 'hover' ? hover : base).push(dark);
        }
      } else {
        const k = d.indexOf(':');
        if (k < 0) continue;
        const dark = declToDark(d.slice(0, k), d.slice(k + 1));
        if (dark) base.push(dark);
      }
    }
    const emit = (decls, suffix) => {
      if (!decls.length) return;
      const wrap = (b) => (at ? `${at} {\n  ${b.replace(/\n/g, '\n  ')}\n}` : b);
      const normal = decls.filter(([p]) => p !== 'divide');
      const divide = decls.find(([p]) => p === 'divide');
      if (normal.length) {
        fileRules.push(wrap(`${sels.map((x) => `html.dark ${x}${suffix}`).join(',\n')} {\n${normal.map(([p, v]) => `  ${p}: ${v};`).join('\n')}\n}`));
      }
      if (divide) {
        fileRules.push(wrap(`${sels.map((x) => `html.dark ${x}${suffix} > :not([hidden]) ~ :not([hidden])`).join(',\n')} {\n  border-color: ${divide[1]};\n}`));
      }
    };
    emit(base, '');
    emit(hover, ':hover');
  }

  let next = text.replace(/\n+$/, '\n');
  if (fileRules.length) {
    next += `\n<style${scoped ? ' scoped' : ''}>\n${MARK}\n${fileRules.join('\n')}\n</style>\n`;
    total += fileRules.length;
  }
  if (next !== raw.replace(/\r\n/g, '\n')) {
    fs.writeFileSync(file, crlf ? next.replace(/\n/g, '\r\n') : next);
    changed++;
  }
}
console.log(`Dark rules: ${total} in ${changed} component(s) updated`);
